import{_ as o,c as t,o as r,ag as a}from"./chunks/framework.Cycwnjj0.js";const f=JSON.parse('{"title":"How to Resolve \\"Request Throttled\\" Error of Amazon API","description":"","frontmatter":{},"headers":[],"relativePath":"guide/miscellaneous/how-to-resolve-request-throttled-error-of-amazon-api.md","filePath":"guide/miscellaneous/how-to-resolve-request-throttled-error-of-amazon-api.md"}'),n={name:"guide/miscellaneous/how-to-resolve-request-throttled-error-of-amazon-api.md"};function s(i,e,l,u,h,c){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="how-to-resolve-request-throttled-error-of-amazon-api" tabindex="-1">How to Resolve &quot;Request Throttled&quot; Error of Amazon API <a class="header-anchor" href="#how-to-resolve-request-throttled-error-of-amazon-api" aria-label="Permalink to &quot;How to Resolve &quot;Request Throttled&quot; Error of Amazon API&quot;">​</a></h1><p>API (Application Programming Interface) is a method we use in our plugin to connect with Amazon to retrieve product information. Our plugin including AzonPress won&#39;t connect to Amazon&#39;s Servers if you don&#39;t have a working API key generated from your Amazon account.</p><h2 id="what-is-the-request-throttled-error" tabindex="-1">What is the &quot;Request Throttled&quot; Error? <a class="header-anchor" href="#what-is-the-request-throttled-error" aria-label="Permalink to &quot;What is the &quot;Request Throttled&quot; Error?&quot;">​</a></h2><p>Before, you could generate an API key after verifying your account, and by using our plugin you can get product details without any restrictions. However, now Amazon has made some changes in its affiliate program.</p><h3 id="a-few-new-rules-set-by-amazon" tabindex="-1">A Few New Rules Set by Amazon: <a class="header-anchor" href="#a-few-new-rules-set-by-amazon" aria-label="Permalink to &quot;A Few New Rules Set by Amazon:&quot;">​</a></h3><ul><li>New Affiliate accounts will only have access to API keys after verifying the shop by completing 3 qualifying sales in the first 180 days and agreeing to comply with the Operating Terms &amp; Conditions.</li><li>After the verification of your new API key, within a few hours, it will start working.</li><li>You may lose access to Product Advertising API unless your account generates a minimum of 3 referring sales in a consecutive 30-day period.</li><li>If you lose access to Product Advertising API 5.0, you can still use other product linking tools to generate revenue, like SiteStripe, the Custom Products feature of AzonPress, etc.</li><li>But, if you want to regain access to Product Advertising API 5.0, you can get it within two days after your required sales are shipped.</li><li>According to Amazon Product Advertising, only 8640 initial usage requests are allowed every day for the first 30-day period. Also, in the last 30 days, each account limit will be based on the revenue performance of Product API.</li></ul><p>Now, when your Amazon Affiliate account does not follow the new rules, you will receive an error text (<strong>Something went wrong. Please check your API keys</strong>) in the API setting page of the <strong>AzonPress Plugin</strong> and this is called the <strong>RequestThrottled Error</strong>.</p><p><strong>Remember</strong>, if you do not follow any rules mentioned above, your API key will be blocked by Amazon and it will not work. In this case, you can not configure this account&#39;s API with the AzonPress plugin.</p><h2 id="how-do-you-check-if-your-api-keys-work" tabindex="-1">How do you check if your API keys work? <a class="header-anchor" href="#how-do-you-check-if-your-api-keys-work" aria-label="Permalink to &quot;How do you check if your API keys work?&quot;">​</a></h2><p>You can check this with the help of <strong>Amazon&#39;s AWS Scratchpad</strong> (Official). The official <strong>Scratchpad</strong> receives a detailed error report related to API keys.</p><p>To test whether API keys working or not, follow the steps with a screenshot below –</p><p>First, go to Amazon&#39;s AWS Scratchpad, click on <strong>SearchItems</strong> from the left sidebar, and a form will appear where you must enter your <strong>Amazon API key ID</strong>, <strong>Access &amp; Secret key</strong>, and <strong>Tracking ID</strong>.</p><p>Then click the <strong>Run Request</strong> button and finally, the result will be displayed under the &quot;<strong>Response types</strong>&quot; section on the current page.</p><h2 id="how-to-resolve-the-requestthrottled-error" tabindex="-1">How to Resolve the &quot;RequestThrottled&quot; error? <a class="header-anchor" href="#how-to-resolve-the-requestthrottled-error" aria-label="Permalink to &quot;How to Resolve the &quot;RequestThrottled&quot; error?&quot;">​</a></h2><p>If your API keys do not work, follow the rules below to resolve the error.</p><ol><li>For newly created API keys, verify this by completing required sales and agreeing with referred operating agreements. Then, wait at least 48 hours for active keys.</li><li>Confirmed that you have generated a minimum of 3 referring sales every 30 days.</li><li>On multiple websites, never use the same API keys if you are not generating enough sales. It will not allow you to create more API requests.</li></ol><p>We can do nothing from our site for API errors, and for more information, you can contact with Amazon Associates team directly at <a href="https://affiliate-program.amazon.com/home/contact" target="_blank" rel="noreferrer">https://affiliate-program.amazon.com/home/contact</a>.</p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',19)])])}const m=o(n,[["render",s]]);export{f as __pageData,m as default};
